quota_scripts.script:
function httpErr(e) {
  var m = e && e.message ? String(e.message) : String(e);
  if (m.indexOf("HTTP ") === 0) return m;
  if (m.indexOf("JSON parse: ") === 0) return "Parse: " + m.slice(12);
  return "Network: " + m;
}
function intVal(v) {
  return typeof v === "number" && Number.isInteger(v) ? v : null;
}
function msToIso(ms) {
  try {
    var iso = new Date(ms).toISOString();
  } catch (e) {
    return null;
  }
  if (ms % 1000 === 0) return iso.slice(0, 19) + "+00:00";
  return iso.slice(0, 23) + "+00:00";
}
function num(v) {
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && !isNaN(Number(v))) return Number(v);
  return 0.0;
}
var base = String(ctx.baseUrl).toLowerCase().indexOf("bigmodel.cn") !== -1
  ? "https://open.bigmodel.cn"
  : "https://api.z.ai";
var body;
try {
  body = http.get(base + "/api/monitor/usage/quota/limit", {
    "Authorization": ctx.apiKey,
    "Content-Type": "application/json"
  });
} catch (e) {
  return { success: false, error: httpErr(e) };
}
if (body == null || typeof body !== "object" || Array.isArray(body)) body = {};
if (body.success === false) {
  return { success: false, error: typeof body.msg === "string" ? body.msg : "Unknown" };
}
if (!("data" in body)) return { success: false, error: "Missing data field" };
var data = body.data;
if (data == null || typeof data !== "object" || Array.isArray(data)) data = {};
var level = typeof data.level === "string" ? data.level : null;
var tiers = [];
var fiveHour = null;
var weekly = null;
var unclassified = [];
if (Array.isArray(data.limits)) {
  for (var i = 0; i < data.limits.length; i++) {
    var item = data.limits[i];
    if (item == null) continue;
    var type = typeof item.type === "string" ? item.type : "";
    var pct = typeof item.percentage === "number" ? item.percentage : 0.0;
    var resetMs = intVal(item.nextResetTime);
    var resetIso = resetMs === null ? null : msToIso(resetMs);
    if (type.toLowerCase() === "tokens_limit") {
      var entry = { resetMs: resetMs, pct: pct, resetIso: resetIso };
      var unit = intVal(item.unit);
      if (unit === 3 && fiveHour === null) fiveHour = entry;
      else if (unit === 6 && weekly === null) weekly = entry;
      else unclassified.push(entry);
    } else if (type.toLowerCase() === "time_limit") {
      var usage = num(item.usage);
      var remaining = num(item.remaining);
      tiers.push({
        name: "mcp_monthly",
        utilization: pct,
        resets_at: resetIso,
        limit: usage > 0.0 ? usage : null,
        remaining: remaining > 0.0 ? remaining : null
      });
    }
  }
  unclassified.sort(function (a, b) {
    if ((a.resetMs === null) !== (b.resetMs === null)) return a.resetMs === null ? -1 : 1;
    if (a.resetMs === null) return 0;
    return a.resetMs - b.resetMs;
  });
  for (var j = 0; j < unclassified.length; j++) {
    if (fiveHour === null) fiveHour = unclassified[j];
    else if (weekly === null) weekly = unclassified[j];
  }
  if (fiveHour !== null) {
    tiers.unshift({ name: "five_hour", utilization: fiveHour.pct, resets_at: fiveHour.resetIso });
  }
  if (weekly !== null) {
    var pos = 0;
    while (pos < tiers.length && tiers[pos].name !== "mcp_monthly") pos++;
    tiers.splice(pos, 0, { name: "weekly_limit", utilization: weekly.pct, resets_at: weekly.resetIso });
  }
}
return {
  success: true,
  error: null,
  balance: null,
  coding_plan: { level: level, tiers: tiers }
};
